<?php
require __DIR__.'/bootstrap.php';if(empty($_SESSION['gh_user_id']))gh_redirect('Log in to open the tracker.','error','index.php#login');
$count=$pdo->prepare('SELECT COUNT(*) FROM gh_walk_tracks WHERE user_id=?');$count->execute(array($_SESSION['gh_user_id']));$walks=(int)$count->fetchColumn();$points=$pdo->prepare('SELECT COALESCE(SUM(point_count),0) FROM gh_walk_tracks WHERE user_id=?');$points->execute(array($_SESSION['gh_user_id']));$pointCount=(int)$points->fetchColumn();$cities=$pdo->query('SELECT slug,name,region,center_lat,center_lon,default_zoom FROM gh_cities WHERE enabled=1 ORDER BY name')->fetchAll();if(empty($_SESSION['gh_csrf']))$_SESSION['gh_csrf']=bin2hex(random_bytes(24));
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Walk Map | Graffiti Hunter</title><link rel="stylesheet" href="assets/site.css"><link rel="stylesheet" href="https://unpkg.com/maplibre-gl@5.6.0/dist/maplibre-gl.css"><script src="https://unpkg.com/maplibre-gl@5.6.0/dist/maplibre-gl.js"></script></head><body class="dash-body"><header class="site-header"><a class="brand" href="index.php"><span class="brand-mark">GH</span><span>GRAFFITI HUNTER <small>WALK MAP</small></span></a><nav><a href="index.php">Public page</a><a href="connect.php">Connect Android</a><a class="nav-login" href="logout.php">Sign out</a></nav></header><main class="walk-dashboard"><section class="dash-heading"><div><p class="eyebrow dark"><span></span> Private field tracker</p><h1>Hello, <?php echo htmlspecialchars($_SESSION['gh_user_name'],ENT_QUOTES,'UTF-8'); ?>.</h1><p>Your bright routes are streets and paths you have walked. Unvisited streets remain unchanged.</p></div><a class="button primary" href="connect.php">Connect Android app</a></section><section class="dash-stats"><article><b><?php echo $walks; ?></b><span>Walks uploaded</span></article><article><b><?php echo $pointCount; ?></b><span>GPS samples</span></article><article><b><?php echo count($cities); ?></b><span>Supported city</span></article></section><section class="map-shell"><div class="map-toolbar"><label>Map area<select id="city-select"><?php foreach($cities as $city): ?><option value="<?php echo htmlspecialchars($city['slug'],ENT_QUOTES,'UTF-8'); ?>" data-lat="<?php echo $city['center_lat']; ?>" data-lon="<?php echo $city['center_lon']; ?>" data-zoom="<?php echo $city['default_zoom']; ?>"><?php echo htmlspecialchars($city['name'].', '.$city['region'],ENT_QUOTES,'UTF-8'); ?></option><?php endforeach; ?></select></label><div class="map-key"><i></i> Walked route</div><button id="refresh-map" type="button">Refresh</button></div><div id="walk-map" aria-label="Map of walked routes"></div><div id="map-empty">No San Diego walks uploaded yet. Connect the Android app or upload a CSV below.</div></section><section class="dash-lower"><article><h2>Upload a walk CSV</h2><p>Use this to import a file manually. Android sync uses the same secure importer automatically.</p><form action="upload.php" method="post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?php echo htmlspecialchars($_SESSION['gh_csrf'],ENT_QUOTES,'UTF-8'); ?>"><input type="file" name="walk" accept=".csv,text/csv" required><button class="button primary" type="submit">Import walk</button></form></article><article><h2>How highlighting works</h2><p>Each timestamped GPS sample becomes part of a GeoJSON route. The lime line lights up the path you walked. A future map-matching upgrade will snap those points to exact OpenStreetMap street segments.</p></article></section></main><script src="assets/tracker.js"></script></body></html>
